// Converter config for Integration Control Plane (wso2/docs-integrator,
// directory integration-control-plane/, branches
// integration-control-plane/release/<version>). ICP has no site of its own:
// it is the icp/ folder of the Integrator site (branch wso2-integrator), whose
// _category_.json names it "ICP 2.1.0". So it is read from that site's
// versions, only icp/ (`only`), with its sidebar the folder's autogenerated
// slice (`sidebarItems`):
// - main (`next`, a preview never published) from docs/icp/;
// - integration-control-plane/release/2.1.0 from versioned_docs/version-5.1.0/icp/.
// ICP 2.0.0 is the 22 pages inside Integrator 5.0.0 (manage/icp/,
// reference/icp/); Product placement lists only 2.1.0, so they stay there.
// ICP has no Cloud. Links out of icp/ into Integrator go to the legacy site,
// as Integrator's links into icp/ do (ticket 19, Q72).
import integrator from './integrator.mjs';

const LEGACY = 'https://wso2.com/integration-platform/docs/';
// The Integrator site version each ICP Edition is read from.
const SITE_VERSION = { '2.1.0': '5.1.0' };
const sourceVersion = (edition) => SITE_VERSION[edition] ?? edition;

export default {
  slug: 'integration-control-plane',
  source: 'docusaurus',
  sourceRepo: 'wso2/docs-integrator',
  sourceRoot: 'en',
  sourceVersion,
  // Only icp/; its sidebar is the folder, as Docusaurus autogenerates it.
  only: ['icp/'],
  sidebarItems: [{ type: 'autogenerated', dirName: 'icp' }],
  // The pages' legacy URLs are on the Integrator site (/integrator/icp/…).
  legacyBase: (edition) => integrator.legacyBase(sourceVersion(edition)),
  legacySites: { ...integrator.legacySites, 'integration-control-plane': `${LEGACY}integrator/` },
  excluded: [],

  // The Doc space manifest (schemas/docspace.schema.json), written to
  // integration-control-plane/docspace.yaml on every branch.
  docspace: {
    schemaVersion: 1,
    slug: 'integration-control-plane',
    displayName: 'Integration Control Plane',
    editionNames: { selfHosted: 'Integration Control Plane {version}' },
    home: 'integration-platform',
    owners: { team: 'integration-platform-docs' },
    repo: 'wso2/docs-integrator',
    // Hidden during the Pilot: the Pilot repos are generated.
    editLinks: false,
    issues: { repo: 'wso2/docs-integrator' },
    editions: [{ id: '2.1.0', branch: 'integration-control-plane/release/2.1.0' }],
  },
  editions: {
    'self-hosted': {
      displayName: 'Integration Control Plane {version}',
      productName: 'WSO2 Integration Control Plane',
    },
  },

  // The icp/ folder's items (pages and categories, by their sidebar label)
  // re-filed into the sidebar skeleton; the overview is the Edition home.
  topLevel: {
    Overview: { page: 'index' },
    'Get Started with ICP': { page: 'get-started/quick-start' },
    'Install ICP': { page: 'get-started/install-icp' },
    'ICP Console Overview': { page: 'concepts/icp-console-overview' },
    'Connect an Integration to ICP': { page: 'guides/connect-runtime' },
    'Manage Projects': { page: 'guides/manage-projects' },
    'Manage Integrations': { page: 'guides/manage-integrations' },
    'Manage Runtimes': { page: 'guides/manage-runtimes' },
    'Manage Environments': { page: 'guides/manage-environments' },
    'Manage Workflows': { folder: 'guides/manage-workflows' },
    'Access Control': { page: 'guides/access-control' },
    'User Stores': { folder: 'guides/user-stores' },
    'Deploy ICP on Kubernetes': { page: 'deploy-and-operate/deploy-kubernetes' },
    'Configure a Reverse Proxy': { page: 'deploy-and-operate/reverse-proxy' },
    'Encrypt Secrets': { page: 'deploy-and-operate/encrypt-secrets' },
    'Observability Setup': { folder: 'deploy-and-operate/observability-setup' },
    'Server Configuration': { page: 'reference/server-configuration' },
    'Database Configuration': { page: 'reference/database-configuration' },
    'Authentication Configuration': { page: 'reference/authentication-config' },
    'ICP Authentication API': { page: 'reference/auth-api' },
    'ICP Runtime API': { page: 'reference/runtime-api' },
    'ICP Management API': { page: 'reference/management-api' },
  },
  skeleton: [
    { folder: 'get-started', label: 'Get started' },
    { folder: 'guides', label: 'Guides' },
    { folder: 'concepts', label: 'Concepts' },
    { folder: 'reference', label: 'Reference' },
    { folder: 'deploy-and-operate', label: 'Deploy and operate' },
    { folder: 'release-notes', label: 'Release notes' },
  ],
  types: {
    'get-started': 'quick-start',
    guides: 'how-to',
    concepts: 'concept',
    reference: 'reference',
    'deploy-and-operate': 'how-to',
    'release-notes': 'release-notes',
  },
  typeOverrides: {
    index: 'concept',
    'get-started/install-icp': 'how-to',
  },

  admonitions: integrator.admonitions,
  properNouns: [...integrator.properNouns, 'Integration Control Plane', 'ICP Console', 'LDAP', 'SSO', 'JWT', 'Moesif', 'OpenSearch', 'MI'],
};
